"use server";

import { z } from "zod";
import { createHash, randomBytes } from "node:crypto";
import { after } from "next/server";
import { db } from "@/lib/db";
import { hashPassword } from "@/lib/auth";
import { createSession, destroyAllSessions } from "@/lib/session";
import { rateLimit } from "@/lib/security";
import { sendPasswordReset } from "@/lib/email";
import { smtpConfigured } from "@/lib/env";
import { SITE } from "@/lib/site";
import type { FormState } from "./auth";

const hash = (t: string) => createHash("sha256").update(t).digest("hex");
const RESET_TTL_MS = 30 * 60 * 1000;

export async function requestPasswordReset(_: FormState, formData: FormData): Promise<FormState> {
  if (!(await rateLimit("reset-request", 5, 60 * 60))) return { error: "Too many requests. Please try again later." };
  const email = z.email().safeParse(String(formData.get("email") ?? "").trim().toLowerCase());
  if (!email.success) return { fieldErrors: { email: ["Enter a valid email"] } };
  if (!smtpConfigured()) return { error: `Password reset by email isn’t available yet. Please WhatsApp ${SITE.phone} for help.` };

  const user = await db.user.findUnique({ where: { email: email.data } });
  if (user?.isActive) {
    const token = randomBytes(32).toString("base64url");
    await db.passwordResetToken.deleteMany({ where: { userId: user.id } });
    await db.passwordResetToken.create({ data: { userId: user.id, tokenHash: hash(token), expiresAt: new Date(Date.now() + RESET_TTL_MS) } });
    const link = `${SITE.url}/reset-password?token=${token}`;
    after(() => sendPasswordReset(user.email, user.name, link));
  }
  // Same response whether or not the account exists (no account enumeration).
  return { ok: true };
}

const resetSchema = z.object({
  token: z.string().min(20).max(100),
  password: z.string().min(8, "Use at least 8 characters").max(128).regex(/[A-Za-z]/, "Include a letter").regex(/\d/, "Include a number"),
});

export async function resetPassword(_: FormState, formData: FormData): Promise<FormState> {
  if (!(await rateLimit("reset", 10, 60 * 60))) return { error: "Too many attempts. Please try again later." };
  const parsed = resetSchema.safeParse(Object.fromEntries(formData));
  if (!parsed.success) return { fieldErrors: parsed.error.flatten().fieldErrors };
  const record = await db.passwordResetToken.findUnique({ where: { tokenHash: hash(parsed.data.token) }, include: { user: true } });
  if (!record || record.usedAt || record.expiresAt < new Date() || !record.user.isActive) {
    return { error: "This reset link is invalid or has expired. Please request a new one." };
  }
  // Single-use: claim the token atomically before changing the password.
  const claimed = await db.passwordResetToken.updateMany({ where: { id: record.id, usedAt: null }, data: { usedAt: new Date() } });
  if (claimed.count === 0) return { error: "This reset link has already been used." };
  await db.user.update({ where: { id: record.userId }, data: { passwordHash: await hashPassword(parsed.data.password) } });
  await destroyAllSessions(record.userId);
  await createSession(record.userId);
  return { ok: true };
}
